import"./app-C0dFVt1v.js";/* empty css              */window.switchAuthTab=function(e){document.querySelectorAll(`.auth-tabs button`).forEach(t=>{t.classList.toggle(`active`,t.dataset.tab===e)}),document.getElementById(`login-form`).classList.toggle(`active`,e===`login`),document.getElementById(`signup-form`).classList.toggle(`active`,e===`signup`)},window.handleLogin=async function(e){e.preventDefault();let t=document.getElementById(`login-email`).value.trim(),n=document.getElementById(`login-password`).value;try{window.showToast(`Logging in...`);let e=(await window.api.request(`/auth/login`,{method:`POST`,body:JSON.stringify({email:t,password:n})})).data;localStorage.setItem(`accessToken`,e.accessToken),localStorage.setItem(`refreshToken`,e.refreshToken),localStorage.setItem(`currentUser`,JSON.stringify(e.user)),window.showToast(`Welcome back ${e.user.username}`),setTimeout(()=>{window.location.href=`discover.html`},800)}catch(e){window.showToast(e.message||`Login failed`)}return!1},window.handleSignup=async function(e){e.preventDefault();let t=document.getElementById(`signup-username`).value.trim(),n=document.getElementById(`signup-email`).value.trim(),r=document.getElementById(`signup-password`).value;try{window.showToast(`Creating account...`);let e=(await window.api.request(`/auth/register`,{method:`POST`,body:JSON.stringify({username:t,email:n,password:r,displayName:t})})).data;localStorage.setItem(`accessToken`,e.accessToken),localStorage.setItem(`refreshToken`,e.refreshToken),localStorage.setItem(`currentUser`,JSON.stringify(e.user)),window.showToast(`Account created successfully`),setTimeout(()=>{window.location.href=`discover.html`},800)}catch(e){window.showToast(e.message||`Registration failed`)}return!1},window.mockOAuth=function(e){window.showToast(`${e} login coming soon`)};